/// Mask for a non-ship body at `frame_index`, matching `Art.projectile`.
#[inline]
pub fn projectile_mask(body: Body, frame_index: i64) -> Option<&'static Mask> {
    let row = projectile_row(body)?;
    if frame_index < 0 || frame_index >= MAX_FRAMES as i64 {
        return None;
    }
    let id = PROJECTILE_MASK[row][frame_index as usize];
    if id == NO_MASK { None } else { Some(&MASKS[id as usize]) }
}

/// Mask for a ship sprite. `alt` selects the Androsynth blazer strip and the
/// Mmrnmhrm Y-wing strip; every other ship ignores it.
#[inline]
pub fn ship_mask(kind: ShipKind, alt: bool, facing: i64) -> Option<&'static Mask> {
    let id = SHIP_MASK[kind.index()][alt as usize][facing.rem_euclid(16) as usize];
    if id == NO_MASK { None } else { Some(&MASKS[id as usize]) }
}

